draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // tree
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 - 100 + 50*Math.sin(t));
  ctx.stroke();

  // leaves
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100 + 50*Math.sin(t), 20 + 10*Math.cos(t), 0, 2*Math.PI);
  ctx.stroke();

  // thoreau
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 + 50, 20, 0, 2*Math.PI); // head
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 70);
  ctx.lineTo(W/2 - 50, H/2 + 100); // body
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 90);
  ctx.lineTo(W/2 - 70, H/2 + 120); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 90);
  ctx.lineTo(W/2 - 30, H/2 + 120); // leg
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 80);
  ctx.lineTo(W/2 - 70, H/2 + 110); // arm
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 80);
  ctx.lineTo(W/2 - 30, H/2 + 110); // arm
  ctx.stroke();

  // book
  ctx.lineWidth = 2;
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 20, H/2 + 130, 40, 10);

  ctx.restore();
}
